&lt;img title=&quot;Ext&#233;rieur&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Ext&#233;rieur.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Collines&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Collines.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Extraplanaire&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Extraplanaire.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : &lt;a class=&quot;pagelink&quot; href=&quot;Bestiaire-5-(Contenu).html&quot; title=&quot;Bestiaire 5 (Contenu)&quot;&gt;Bestiaire 5 p.280&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 3 200
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Ext&#233;rieur.html&quot; title=&quot;Ext&#233;rieur&quot;&gt;Ext&#233;rieur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Air.html&quot; title=&quot;Air (sous-type)&quot;&gt;Air&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Extraplanaire.html&quot; title=&quot;Extraplanaire (sous-type)&quot;&gt;extraplanaire&lt;/a&gt;) de taille M, N
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +3 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +12
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 19, contact 13, pris au d&#233;pourvu 16 (Dex +3, naturelle +6)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 85 (9d10+36)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +9, &lt;b&gt;Vig&lt;/b&gt; +10, &lt;b&gt;Vol&lt;/b&gt; +6
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;RD&lt;/b&gt; 10/magie ; &lt;b&gt;Immunit&#233;s&lt;/b&gt; &#233;lectricit&#233; ; &lt;b&gt;RM&lt;/b&gt; 18
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m, &lt;a class=&quot;pagelink&quot; href=&quot;Vol-(Capacit&#233;).html&quot; title=&quot;Vol (Ext ou Sur)&quot;&gt;vol&lt;/a&gt; 9 m (parfaite)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; dague de ma&#238;tre, +13/+8 (1d4+5/19-20 plus 1d6 &#233;lectricit&#233;) et dague de ma&#238;tre, +13/+8 (1d4+5/19-20 plus 1d6 &#233;lectricit&#233;) ou 2 coups, +14 (1d4+5 plus 1d6 &#233;lectricit&#233;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; danse attirante, voile &#233;l&#233;mentaire
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 9 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +14)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
&#192; volont&#233; — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bourrasque.html&quot; title=&quot;Bourrasque&quot;&gt;bourrasque&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt; (&#233;lectricit&#233; seulement)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
3/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soins-Importants.html&quot; title=&quot;Soins importants&quot;&gt;soins importants&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Suggestion.html&quot; title=&quot;Suggestion&quot;&gt;suggestion&lt;/a&gt;&lt;/i&gt; (DD 18)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boule-De-Foudre.html&quot; title=&quot;Boule de foudre&quot;&gt;boule de foudre&lt;/a&gt;&lt;/i&gt; (DD 19), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation de la magie&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 20, &lt;b&gt;Dex&lt;/b&gt; 17, &lt;b&gt;Con&lt;/b&gt; 19, &lt;b&gt;Int&lt;/b&gt; 14, &lt;b&gt;Sag&lt;/b&gt; 11, &lt;b&gt;Cha&lt;/b&gt; 20
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +9 ; &lt;b&gt;BMO&lt;/b&gt; +14 ; &lt;b&gt;DMD&lt;/b&gt; 27
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-Sp&#233;ciale-Renforc&#233;e.html&quot; title=&quot;Attaque sp&#233;ciale renforc&#233;e&quot;&gt;Attaque sp&#233;ciale renforc&#233;e&lt;/a&gt; (danse attirante), &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-R&#233;flexes.html&quot; title=&quot;Attaques r&#233;flexes&quot;&gt;Attaques r&#233;flexes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Combat-&#192;-Deux-Armes.html&quot; title=&quot;Combat &#224; deux armes&quot;&gt;Combat &#224; deux armes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Double-Frappe.html&quot; title=&quot;Double frappe&quot;&gt;Double frappe&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Combat-&#192;-Deux-Armes.html&quot; title=&quot;Science du combat &#224; deux armes&quot;&gt;Science du combat &#224; deux armes&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +15, &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; +17, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (une au choix) +14, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +15, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +12, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +11, &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (danse) +21, &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; +15 ; &lt;b&gt;Modificateurs raciaux&lt;/b&gt; +4 en Repr&#233;sentation (danse)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; a&#233;rien, commun
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;&#201;cologie&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Environnement&lt;/b&gt; collines ou montagnes (plan de l’Air)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Organisation&lt;/b&gt; solitaire, couple ou troupe (3-6)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tr&#233;sor&lt;/b&gt; standard (2 &lt;a class=&quot;pagelink&quot; href=&quot;Dague-(Arme).html&quot; title=&quot;Dague&quot;&gt;dagues&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armesmaitre.html&quot; title=&quot;arme de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Pouvoirs sp&#233;ciaux&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Danse attirante (Sur).&lt;/b&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le veela peut contraindre une cible situ&#233;e dans son champ de vision &#224; se joindre &#224; sa danse. La cible doit r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; DD 21, sans quoi elle se sent oblig&#233;e de danser avec le veela pendant une minute au maximum. &#192; la fin de chacun de ses tours, elle doit tenter un test de &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (danse) oppos&#233; &#224; celui du veela. Si le r&#233;sultat de son test est inf&#233;rieur &#224; celui du veela, elle subit un &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Affaiblissement temporaire (Ext ou Sur)&quot;&gt;affaiblissement temporaire&lt;/a&gt; de 1d4 points de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; et se retrouve &lt;a class=&quot;pagelink&quot; href=&quot;../&#201;tats pr&#233;judiciables#Fatigu&#233;

Un personnage fatigu&#233; est dans l’incapacit&#233; de courir et de charger/-Il-Subit-Un-Malus-De--2-En-Force-Ainsi-Qu’En-Dext&#233;rit&#233;.-La-Fatigue-Se-Dissipe-Au-Bout-De-Huit-Heures-De-Repos-Total.-Un-Personnage-Fatigu&#233;-Devient-&#201;puis&#233;-D&#232;s-Qu’Il-Fait-Quoi-Que-Ce-Soit-Qui-Causerait-Un-Nouvel-&#201;tat-Fatigu&#233;..html&quot; title=&quot;Fatigu&#233;&quot;&gt;fatigu&#233;e&lt;/a&gt;. Le veela r&#233;cup&#232;re 5 points de vie pour chaque point d’affaiblissement de Constitution ainsi inflig&#233;. Les points r&#233;cup&#233;r&#233;s en exc&#232;s de son maximum de points de vie deviennent des &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort#Pvtemporaires.html&quot; title=&quot;points de vie temporaires&quot;&gt;points de vie temporaires&lt;/a&gt; qui persistent une heure au maximum avant de dispara&#238;tre. Tant que le veela et sa victime dansent, ils sont tous les deux prot&#233;g&#233;s contre les attaques comme s’ils b&#233;n&#233;ficiaient d’un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sanctuaire.html&quot; title=&quot;Sanctuaire&quot;&gt;sanctuaire&lt;/a&gt;&lt;/i&gt; (DD 18). Si la cible de la danse attirante du veela obtient un r&#233;sultat sup&#233;rieur &#224; celui du veela lors du test de Repr&#233;sentation oppos&#233;, elle met fin &#224; la danse attirante et b&#233;n&#233;ficie des effets du pouvoir magique &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soins-Importants.html&quot; title=&quot;Soins importants&quot;&gt;soins importants&lt;/a&gt;&lt;/i&gt; du veela (s’il lui reste des utilisations quotidiennes &#224; d&#233;penser), ce qui provoque la d&#233;pense d’une utilisation quotidienne de ce pouvoir. Une cible qui r&#233;ussit son jet de sauvegarde contre la danse attirante du veela ne peut plus &#234;tre affect&#233;e par le pouvoir de ce veela pendant 24 heures. Le DD du jet de sauvegarde est bas&#233; sur le Charisme.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Voile &#233;l&#233;mentaire (Sur).&lt;/b&gt; Le lien entre le veela et un &#233;l&#233;ment particulier se manifeste sous forme d’un exc&#232;s d’&#233;nergie qui impr&#232;gne les armes de corps &#224; corps qu’il manie. Il inflige donc 1d6 points de d&#233;g&#226;ts suppl&#233;mentaires quand il touche sa cible au corps &#224; corps. Ce sont des d&#233;g&#226;ts d’&#233;lectricit&#233; pour les veelas de l’air, des d&#233;g&#226;ts contondants pour ceux &lt;a class=&quot;pagelink&quot; href=&quot;Veela-De-La-Terre.html&quot; title=&quot;Veela, Veela de la terre&quot;&gt;de la terre&lt;/a&gt;, des d&#233;g&#226;ts de feu pour ceux &lt;a class=&quot;pagelink&quot; href=&quot;Veela-Du-Feu.html&quot; title=&quot;Veela, Veela du feu&quot;&gt;du feu&lt;/a&gt; et des d&#233;g&#226;ts de froid pour ceux &lt;a class=&quot;pagelink&quot; href=&quot;Veela-De-Leau.html&quot; title=&quot;Veela, Veela de l&amp;#39;eau&quot;&gt;de l’eau&lt;/a&gt;. De plus, le veela peut s’envelopper d’un halo d’&#233;nergie lumineuse par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;. Ce ph&#233;nom&#232;ne reproduit les effets d’un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-De-Feu.html&quot; title=&quot;Bouclier de feu&quot;&gt;bouclier de feu&lt;/a&gt;&lt;/i&gt; (NLS 9) mais inflige des d&#233;g&#226;ts du m&#234;me type que les d&#233;g&#226;ts de corps &#224; corps suppl&#233;mentaires. Il faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; pour activer ou d&#233;sactiver cet effet.
&lt;/div&gt;&lt;br /&gt;&lt;/div&gt;&lt;/td&gt;
&lt;td&gt;&lt;div&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 0 0; margin: 0 0 4px 8px&quot;&gt;
&lt;table CLASS=&quot;tablo autoalt&quot;&gt;&lt;caption&gt;Variantes de veela&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Nom&lt;/td&gt;&lt;td&gt;FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Veela-De-Lair.html&quot; title=&quot;Veela, Veela de l&amp;#39;air&quot;&gt;Veela de l&#39;air&lt;/a&gt;&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Veela-De-La-Terre.html&quot; title=&quot;Veela, Veela de la terre&quot;&gt;Veela de la terre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Veela-De-Leau.html&quot; title=&quot;Veela, Veela de l&amp;#39;eau&quot;&gt;Veela de l&#39;eau&lt;/a&gt;&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Veela-Du-Feu.html&quot; title=&quot;Veela, Veela du feu&quot;&gt;Veela du feu&lt;/a&gt;&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;i&gt;Ce mince humano&#239;de androgyne pr&#233;sente une gr&#226;ce surnaturelle et une peau &#224; la couleur surprenante.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Capricieux mais s&#233;duisants, les veelas sont des esprits &#233;l&#233;mentaires mat&#233;rialis&#233;s. Sur les plans &#201;l&#233;mentaires, ils baignent dans les &#233;nergies volatiles de l’&#233;l&#233;ment dont ils tirent leur puissance, mais perdent une part de l’&#233;nergie &#233;l&#233;mentaire qui sature leur corps lorsqu’ils se mat&#233;rialisent sur les autres plans. Pour compenser cela, ils sont capables de siphonner la vitalit&#233; des autres &#234;tres vivants quand ces derniers prennent part &#224; l’une de leurs antiques danses. En g&#233;n&#233;ral, un veela demande la permission de son partenaire avant de l’inviter &#224; danser et le laisse ravi mais &#233;puis&#233; &#224; la fin de la chor&#233;graphie. Il faut que la situation soit vraiment d&#233;sesp&#233;r&#233;e pour qu’un veela recoure &#224; la danse de mani&#232;re offensive. Les rares individus qui parviennent &#224; &#233;galer la gr&#226;ce des mouvements de ces esprits danseurs gagnent leur respect et les poussent parfois &#224; partager une partie de leurs pouvoirs magiques b&#233;n&#233;fiques.&lt;br /&gt;&lt;br /&gt;Un veela mesure 1,80 m&#232;tre pour 70 kilos environ.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
